    const name = scene.getName();
    ui.focus = ({ Menu: 'play', Lobby: 'start', Customize: 'body0', Shop: 'body0', Settings: 'music', Credits: 'back' })[name] || 'back';
    if (!GLOMP.save.data) GLOMP.save.load();
